(function(){
  var STORAGE_USERS = 'csp.users';
  var STORAGE_SESSION = 'csp.session';
  var form = document.getElementById('reg');
  var status = document.getElementById('status');
  var submitBtn = document.getElementById('submit');
  var fields = {
    username: document.getElementById('username'),
    email: document.getElementById('email'),
    dob: document.getElementById('dob'),
    password: document.getElementById('password'),
    confirm: document.getElementById('confirm'),
    terms: document.getElementById('terms')
  };
  var errs = {
    username: document.getElementById('username-err'),
    email: document.getElementById('email-err'),
    dob: document.getElementById('dob-err'),
    password: document.getElementById('pw-err'),
    confirm: document.getElementById('confirm-err'),
    terms: document.getElementById('terms-err')
  };

  function loadUsers(){
    try{ return JSON.parse(localStorage.getItem(STORAGE_USERS) || '{}'); }
    catch(e){ return {}; }
  }
  function saveUsers(u){ localStorage.setItem(STORAGE_USERS, JSON.stringify(u)); }

  function setError(name, msg){
    var input = fields[name];
    var out = errs[name];
    if(msg){
      if(input && input.type !== 'checkbox') input.setAttribute('aria-invalid','true');
      out.textContent = msg;
    } else {
      if(input && input.type !== 'checkbox') input.removeAttribute('aria-invalid');
      out.textContent = '';
    }
  }

  function emailValid(v){ return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v); }
  function pwStrong(v){ return v.length >= 8 && /[A-Za-z]/.test(v) && /\d/.test(v); }

  function validateField(name){
    var v = (fields[name].value || '').trim();
    switch(name){
      case 'username':
        if(!v) return 'Please choose a username.';
        if(v.length < 3) return 'Username must be at least 3 characters.';
        if(v.length > 24) return 'Username must be at most 24 characters.';
        if(!/^[A-Za-z0-9_]+$/.test(v)) return 'Use letters, numbers, or underscore only.';
        var users = loadUsers();
        if(users[v.toLowerCase()]) return 'That username is already taken.';
        return '';
      case 'email':
        if(!v) return 'Please enter your email address.';
        if(!emailValid(v)) return 'Enter a valid email address.';
        var u2 = loadUsers();
        var em = v.toLowerCase();
        for(var k in u2){ if(u2[k].email === em) return 'An account with that email already exists.'; }
        return '';
      case 'dob':
        if(!v) return '';
        var d = new Date(v);
        if(isNaN(d.getTime())) return 'Enter a valid date.';
        var today = new Date(); today.setHours(0,0,0,0);
        if(d > today) return 'Date of birth cannot be in the future.';
        var age = (today - d) / (365.25*24*60*60*1000);
        if(age > 120) return 'Please enter a realistic date of birth.';
        return '';
      case 'password':
        if(!fields.password.value) return 'Please choose a password.';
        if(!pwStrong(fields.password.value))
          return 'Use at least 8 characters with a letter and a number.';
        return '';
      case 'confirm':
        if(!fields.confirm.value) return 'Please confirm your password.';
        if(fields.password.value !== fields.confirm.value)
          return 'Passwords do not match.';
        return '';
      case 'terms':
        if(!fields.terms.checked) return 'You must accept the Terms of Service to continue.';
        return '';
    }
    return '';
  }

  function showStatus(kind, msg){
    status.className = 'status show ' + kind;
    status.textContent = msg;
  }
  function clearStatus(){
    status.className = 'status';
    status.textContent = '';
  }

  Object.keys(fields).forEach(function(name){
    var el = fields[name];
    var evt = (el.type === 'checkbox') ? 'change' : 'input';
    el.addEventListener(evt, function(){
      var msg = validateField(name);
      setError(name, msg);
      if(name === 'password' && fields.confirm.value){
        var cmsg = validateField('confirm');
        setError('confirm', cmsg);
      }
      if(status.classList.contains('err')) clearStatus();
    });
    el.addEventListener('blur', function(){
      var msg = validateField(name);
      setError(name, msg);
    });
  });

  document.querySelectorAll('.toggle').forEach(function(btn){
    btn.addEventListener('click', function(){
      var id = btn.getAttribute('data-target');
      var input = document.getElementById(id);
      var showing = input.type === 'text';
      input.type = showing ? 'password' : 'text';
      btn.setAttribute('aria-pressed', String(!showing));
      btn.setAttribute('aria-label', showing ? 'Show ' + (id==='password'?'password':'confirm password') : 'Hide ' + (id==='password'?'password':'confirm password'));
      btn.textContent = showing ? 'Show' : 'Hide';
      input.focus();
    });
  });

  form.addEventListener('submit', function(e){
    e.preventDefault();
    clearStatus();
    var firstBad = null;
    Object.keys(fields).forEach(function(name){
      var msg = validateField(name);
      setError(name, msg);
      if(msg && !firstBad) firstBad = fields[name];
    });
    if(firstBad){
      showStatus('err', 'Please fix the highlighted fields and try again.');
      firstBad.focus();
      return;
    }
    submitBtn.disabled = true;
    submitBtn.textContent = 'Creating account…';
    setTimeout(function(){
      var users = loadUsers();
      var username = fields.username.value.trim();
      var email = fields.email.value.trim().toLowerCase();
      users[username.toLowerCase()] = {
        email: email,
        dob: fields.dob.value || null,
        createdAt: new Date().toISOString()
      };
      saveUsers(users);
      try{ sessionStorage.setItem(STORAGE_SESSION, username); }catch(_){}
      showStatus('ok', 'Account created for ' + username + '. Check ' + email + ' for a verification link.');
      form.reset();
      Object.keys(errs).forEach(function(k){ setError(k, ''); });
      document.querySelectorAll('.toggle').forEach(function(b){
        var id = b.getAttribute('data-target');
        var input = document.getElementById(id);
        if(input.type === 'text'){
          input.type = 'password';
          b.setAttribute('aria-pressed','false');
          b.textContent = 'Show';
        }
      });
      submitBtn.disabled = false;
      submitBtn.textContent = 'Create account';
    }, 350);
  });
})();
</script>
</body>
</html>
